nextflow_process {
    name "BEDTOOLS_INTERSECT"
    script "../main.nf"
    process "BEDTOOLS_INTERSECT"

    test("intersect target and truth territory") {
        options "-with-docker"

        when {
            process {
                """
                input[0] = record(
                    id: 'sample',
                    target: file("${moduleDir}/tests/data/target.bed", checkIfExists: true),
                    summary: file("${moduleDir}/tests/data/sample.mosdepth.summary.txt", checkIfExists: true)
                )
                input[1] = file("${moduleDir}/tests/data/truth.bed", checkIfExists: true)
                """
            }
        }

        then {
            assert process.success
            assert file(process.out[0].bed[0]).text.trim() == 'chr1\t1100\t1400'
        }
    }
}
